# Simple C code demonstrating dynamic linking (Illustrative - actual implementation needs system calls)
#include <stdio.h>
#include <dlfcn.h>
int main() {
  void *handle = dlopen("./mylib.so", RTLD_LAZY);
  if (!handle) {
    fprintf(stderr, "dlopen() error: %s\n", dlerror());
    return 1;
  }
  void (*my_function)() = dlsym(handle, "my_function");
  if (!my_function) {
    fprintf(stderr, "dlsym() error: %s\n", dlerror());
    dlclose(handle);
    return 1;
  }
  (*my_function)();
  dlclose(handle);
  return 0;
}
